package com.zerotrust.internalresource.audit;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.slf4j.MDC;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.UUID;
@Component("traceRequestContextFilter") @Order(Ordered.HIGHEST_PRECEDENCE) public class RequestContextFilter extends OncePerRequestFilter{public static final String TRACE_ID_ATTRIBUTE=RequestContextFilter.class.getName()+".traceId";public static final String REQUEST_ID_ATTRIBUTE=RequestContextFilter.class.getName()+".requestId";protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String trace=valueOrGenerate(request.getHeader("X-Trace-Id"));String requestId=valueOrGenerate(request.getHeader("X-Request-Id"));request.setAttribute(TRACE_ID_ATTRIBUTE,trace);request.setAttribute(REQUEST_ID_ATTRIBUTE,requestId);response.setHeader("X-Trace-Id",trace);MDC.put("traceId",trace);MDC.put("requestId",requestId);try{chain.doFilter(request,response);}finally{MDC.remove("traceId");MDC.remove("requestId");}}private String valueOrGenerate(String value){return value==null||value.isBlank()?UUID.randomUUID().toString():value;}}
